    const act={svc:1,ivc:1,pv1:1,pv2:1,raRv:ph==="v"?0:ph==="a"?1:.35,laLv:ph==="v"?0:ph==="a"?1:.35,rvPa:ph==="v"?1:0,lvAo:ph==="v"?1:0};
