  txt(300,432,"O₂ to cells · CO₂ picked up","font:600 13px Outfit,sans-serif",C.soft,sys);
  const side=(x,y,a,b,col,p)=>{txt(x,y,a,"font:700 13px Outfit,sans-serif",col,p);txt(x,y+16,b,"font:600 12px Outfit,sans-serif",C.soft,p);};
  side(92,150,"Pulmonary artery","to the lungs",C.vein,pulm);side(520,150,"Pulmonary veins","back to the heart",C.art,pulm);
  side(520,350,"Aorta","to the body",C.art,sys);side(68,330,"Vena cava","back to the heart",C.vein,sys);
