  // build cumulative lengths
  const tmp=S("path",{fill:"none",stroke:"none"},svg);let d="",cum=[0];segs.forEach(s=>{d+=(d?" ":"")+s[0];tmp.setAttribute("d",d);cum.push(tmp.getTotalLength());});
  const L=cum[cum.length-1];
  const P=S("g",null,svg);const N=58;const dots=[];for(let i=0;i<N;i++)dots.push({s:i*L/N,e:S("circle",{r:4.5},P)});
  function colAt(s){let i=0;while(i<segs.length-1&&s>cum[i+1])i++;const k=segs[i][1],u=(s-cum[i])/(cum[i+1]-cum[i]);
    return{c:k===0?C.vein:k===2?C.art:k===1?mix(C.vein,C.art,u):mix(C.art,C.vein,u),loop:segs[i][2]};}
