  function setShow(k){show=k;pulm.style.opacity=k==="s"?.22:1;sys.style.opacity=k==="p"?.22:1;fr.chip.textContent=k==="both"?"Both loops":k==="p"?"Lung loop":"Body loop";fr.chip.style.background=k==="p"?C.teal:k==="s"?C.coral:C.navy;fr.say(info[k][0],info[k][1]);bs.forEach(b=>b.setAttribute("aria-pressed",b.dataset.k===k));}
