  lung("M282 150 C244 136 190 154 170 222 C152 290 154 346 172 370 C214 362 256 362 282 352 Z");
  lung("M318 150 C356 136 410 154 430 222 C448 290 446 346 428 370 C392 364 360 360 336 352 C340 330 318 318 318 300 Z");
  const tree=S("g",{stroke:"#b4584d","stroke-width":2.4,fill:"none","stroke-linecap":"round",opacity:.7},LG);
  ["M268 186 L238 226 L214 262","M238 226 L246 280 L232 320","M246 280 L270 318","M214 262 L196 300","M332 186 L362 226 L386 262","M362 226 L354 280 L368 320","M354 280 L330 318","M386 262 L404 300"].forEach(d=>S("path",{d},tree));
  // trachea + bronchi
