if(SCI&&window.CATALYST_WEEKLY&&typeof COURSE!=="undefined"){try{let n=0;for(const id in CATALYST_WEEKLY){const l=COURSE.lessons.find(x=>x.id===id);if(!l||!Array.isArray(l.bank))continue;const have=new Set(l.bank.map(q=>q.id));CATALYST_WEEKLY[id].forEach(q=>{if(q&&q.id&&!have.has(q.id)){l.bank.push(q);n++;}});}if(n&&typeof renderCourse==="function")renderCourse();}catch(e){}}

