document.body.appendChild(root);
const $=s=>root.querySelector(s),bub=$(".cx-sbub"),inp=$("input"),res=$(".cx-sres"),acts=$(".cx-sacts"),tipbox=$(".cx-tipbox"),label=$(".cx-slabel");
const esc=s=>String(s==null?"":s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
