  acts.innerHTML=(w==="lesson"?'<button type="button" class="p" data-a="quick">Quick test now</button>':"")+(D.length>1?'<button type="button" data-a="tip">Another tip</button>':"")+'<button type="button" data-a="plan">Exam plan</button>';
